    let mut fz_h = vec![0.0f64; svN];
    let mut fz_l = vec![0.0f64; svN];
    let mut fz_c = vec![0.0f64; svN];
    let mut fz_v = vec![0.0f64; svN];
    let mut fz_oi = vec![0.0f64; svN];
