                    if stu.update_and_fill(&fz_o[p..], &fz_h[p..], &fz_l[p..], &fz_c[p..], &mut u0[..0]).is_ok() { ufill_ok = false; }
                    if stu.out_range() != r0 { ufill_ok = false; }
