                            for t in (svN - p)..svN { if u0[t] != -1.2345678901234e300f64 { ufill_ok = false; } }
                            range_checked = 1; range_legs += 1; range_sites |= 4;
                            if stu.out_range().beg_idx != beg || stu.out_range().count != nb { ufill_ok = false; range_ok = false; }
