                            let Ok(up) = st.update(fz_c[t], fz_v[t]) else { all_ok = false; if diag.is_empty() { diag = format!(",\"updateRejected\":{}", t); } break; };
                            if pk.to_bits() != up.to_bits() { peek_all = false; }
